import { StudentProfileData, NutritionPlan } from '../types';

export interface NutritionEngineInput {
  student: StudentProfileData;
  conditionName?: string;
  doctorNotes?: string;
  preferences?: string;
}

export const NUTRITION_ENGINE_DISCLAIMER =
  'This educational meal plan is generated by the CarePlus Rule-Based Nutrition Engine (Deterministic Clinical Fallback). It is not an autonomous medical prescription. Licensed clinician review and approval is required before clinical publishing.';

/**
 * CarePlus Rule-Based Nutrition Engine (Deterministic Clinical Fallback).
 * Evaluates physiological vitals, declared food allergies, and clinical flags
 * with zero hallucination and strict deterministic safety boundaries.
 */
export function generateAINutritionRecommendation(input: NutritionEngineInput): NutritionPlan {
  const { student, conditionName, doctorNotes, preferences } = input;
  const bmi = student.bmi || 22;
  const allergies = (student.criticalAllergies || []).map((a) => a.toLowerCase().trim());
  const cond = (conditionName || '').toLowerCase().trim();

  let goal = 'Balanced collegiate wellness, immunity support & sustained cognitive focus';
  let breakfast = ['Whole grain steel-cut oats with blueberries & flaxseed', '1 glass of warm lemon water or skim milk'];
  let midMorning = ['Fresh crisp apple or seasonal citrus', 'Handful of raw walnuts'];
  let lunch = ['Grilled protein bowl (paneer/tofu/chicken) with steamed brown rice', 'Mixed green garden salad with olive oil & lemon'];
  let evening = ['Herbal green tea or chamomile infusion', 'Whole grain toast with sliced avocado'];
  let dinner = ['Warm yellow lentil dal or vegetable broth', 'Steamed seasonal greens & roasted sweet potato', 'Baked lean protein'];
  let foodsToLimit = ['Excessive caffeine energy drinks', 'Ultra-processed deep-fried cafeteria snacks', 'Refined sugar confectioneries'];
  let targetCalories = 2100;
  let proteinG = 75;
  let carbsG = 260;
  let fatG = 65;

  // Condition-specific rules
  if (cond.includes('bronchitis') || cond.includes('asthma') || cond.includes('respiratory')) {
    goal = 'Respiratory airway inflammation reduction, mucosal clearance & immune acceleration';
    breakfast = ['Warm rolled oats with raw honey, turmeric & blueberries', 'Warm ginger-tulsi herbal infusion'];
    midMorning = ['Fresh sweet orange or amla (High Vitamin C)', 'Soaked almonds'];
    lunch = ['Warm chicken/lentil turmeric vegetable broth', 'Steamed quinoa with baby spinach'];
    evening = ['Warm golden turmeric milk with black pepper', 'Roasted pumpkin seeds'];
    dinner = ['Steamed fish or soft tofu with roasted sweet potato & steamed broccoli', 'Warm clear vegetable soup'];
    foodsToLimit = ['Chilled ice beverages', 'Heavy mucous-producing dairy', 'Deep fried and greasy items'];
    targetCalories = 2200;
    proteinG = 80;
  } else if (cond.includes('fever') || cond.includes('infection') || cond.includes('flu')) {
    goal = 'Electrolyte replenishment, gentle gastric tolerance & fever convalescence';
    breakfast = ['Rice porridge (kanji) with mild ginger', 'Coconut water with pinch of rock salt'];
    midMorning = ['Pomegranate juice or tender watermelon cubes'];
    lunch = ['Soft khichdi (rice & yellow moong dal)', 'Steamed carrots & zucchini'];
    evening = ['Warm mint & coriander tea', 'Light vegetable broth'];
    dinner = ['Clear vegetable soup with soft tofu cubes', 'Steamed idli or soft flatbread'];
    foodsToLimit = ['Spicy curries', 'Heavy red meats', 'Cold refrigerated items'];
    targetCalories = 1950;
    proteinG = 65;
  } else if (bmi < 18.5) {
    goal = 'Nutrient-dense healthy caloric surplus & lean muscle strength support';
    breakfast = ['Whole milk banana-date smoothie with pumpkin seed powder', 'Scrambled eggs or paneer scramble on sourdough'];
    midMorning = ['Greek yogurt with honey and chia-oat granola'];
    lunch = ['Quinoa & avocado protein bowl with chickpeas', 'Whole wheat pita with olive oil hummus'];
    evening = ['Trail mix with raisins, sunflower seeds & dark chocolate nibs', 'Fruit smoothie'];
    dinner = ['Grilled paneer / lean meat with baked buttered potato and sautéed greens'];
    foodsToLimit = ['Empty sugar beverages that blunt appetite', 'Skipping scheduled meals'];
    targetCalories = 2600;
    proteinG = 95;
    carbsG = 330;
    fatG = 85;
  } else if (bmi > 25.0) {
    goal = 'Metabolic vitality, insulin sensitivity, high-fiber satiety & active hydration';
    breakfast = ['Spinach, mushroom & bell pepper egg white (or besan) omelet', 'Unsweetened green tea'];
    midMorning = ['Cucumber & carrot sticks with fresh mint chutney'];
    lunch = ['Massaged kale & chickpea salad with lemon-mustard vinaigrette', 'Steamed sprouted moong bowl'];
    evening = ['Roasted black chana with spiced green tea'];
    dinner = ['Grilled zucchini with baked spiced tofu or grilled white fish', 'Clear tomato-coriander soup'];
    foodsToLimit = ['High-fructose corn syrup beverages', 'Late-night high-carb snacking', 'Processed bakery items'];
    targetCalories = 1800;
    proteinG = 90;
    carbsG = 175;
    fatG = 45;
  }

  // Multi-allergen strict elimination and substitution filters
  if (allergies.some((a) => a.includes('peanut'))) {
    breakfast = breakfast.map((b) => b.replace(/peanut/gi, 'almond'));
    midMorning = midMorning.map((m) => m.replace(/peanut|walnut/gi, 'sunflower seeds'));
    lunch = lunch.map((l) => l.replace(/peanut/gi, 'sesame'));
    dinner = dinner.map((d) => d.replace(/peanut/gi, 'roasted squash'));
    foodsToLimit.push('ALL Peanuts, peanut butter & peanut oil (Strict allergy flag)');
  }

  if (allergies.some((a) => a.includes('tree nut') || a.includes('almond') || a.includes('walnut') || a.includes('cashew'))) {
    midMorning = midMorning.map((m) => m.replace(/walnut|almond|cashew|nut/gi, 'pumpkin seeds'));
    evening = evening.map((e) => e.replace(/walnut|almond|nut/gi, 'sunflower seeds'));
    foodsToLimit.push('Tree nuts (Almonds, Walnuts, Cashews, Pistachios)');
  }

  if (allergies.some((a) => a.includes('dairy') || a.includes('lactose') || a.includes('milk'))) {
    const swapDairy = (s: string) =>
      s
        .replace(/paneer/gi, 'tofu')
        .replace(/greek yogurt/gi, 'coconut yogurt')
        .replace(/skim milk|whole milk|milk|yogurt/gi, 'oat milk or calcium-fortified soy milk')
        .replace(/buttered/gi, 'olive-oil roasted');
    breakfast = breakfast.map(swapDairy);
    midMorning = midMorning.map(swapDairy);
    lunch = lunch.map(swapDairy);
    evening = evening.map(swapDairy);
    dinner = dinner.map(swapDairy);
    foodsToLimit.push('Dairy products, cow milk, cheese & paneer (Lactose/Dairy flag)');
  }

  if (allergies.some((a) => a.includes('gluten') || a.includes('wheat') || a.includes('celiac'))) {
    breakfast = breakfast.map((b) => b.replace(/whole grain|sourdough|oat/gi, 'gluten-free rolled oats or millet bread'));
    lunch = lunch.map((l) => l.replace(/whole wheat pita/gi, 'corn tortillas'));
    evening = evening.map((e) => e.replace(/whole grain toast/gi, 'rice cakes'));
    dinner = dinner.map((d) => d.replace(/flatbread/gi, 'brown rice or buckwheat roti'));
    foodsToLimit.push('Gluten-containing grains (Wheat, Barley, Rye, Semolina, Maida)');
  }

  if (allergies.some((a) => a.includes('egg'))) {
    breakfast = breakfast.map((b) => b.replace(/egg white|scrambled eggs|boiled eggs|egg/gi, 'tofu scramble with nutritional yeast'));
    foodsToLimit.push('Whole eggs, egg whites, albumin & egg wash coatings');
  }

  if (allergies.some((a) => a.includes('seafood') || a.includes('fish') || a.includes('shellfish') || a.includes('prawn'))) {
    lunch = lunch.map((l) => l.replace(/fish|prawn|shrimp/gi, 'grilled paneer / baked tofu'));
    dinner = dinner.map((d) => d.replace(/fish|prawn|shrimp|seafood/gi, 'lentil loaf or steamed tofu'));
    foodsToLimit.push('Marine products, shellfish, crustacean extracts & fish sauce');
  }

  if (allergies.some((a) => a.includes('soy') || a.includes('soya'))) {
    lunch = lunch.map((l) => l.replace(/tofu|soya/gi, 'kidney beans or chickpeas'));
    dinner = dinner.map((d) => d.replace(/tofu|soya/gi, 'paneer or lentils'));
    foodsToLimit.push('Soy protein, edamame, tofu & soy sauce');
  }

  return {
    id: `nut_${Date.now()}`,
    studentId: student.studentId,
    goal: `${goal}${preferences ? ` [Pref: ${preferences}]` : ''}${doctorNotes ? ` — Clinician Note: ${doctorNotes}` : ''}`,
    aiSuggested: true,
    doctorApproved: false,
    reviewDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    targetCalories,
    proteinG,
    carbsG,
    fatG,
    meals: {
      breakfast,
      midMorning,
      lunch,
      evening,
      dinner
    },
    foodsToLimit,
    encouragingNotes: `${NUTRITION_ENGINE_DISCLAIMER} Designed for ${student.name} based on screening BMI ${bmi} and observed medical flags.`
  };
}
